<script setup lang="ts">
import { ref,onMounted } from 'vue';import { request } from '../crm-api';
const props=defineProps<{inquiries:{id:number;company:string}[];locale:string}>();
const tx=(z:string,e:string)=>props.locale==='zh'?z:e;
const messages=ref<{id:string;sender:string;subject:string;body:string;created_at:string}[]>([]),selection=ref<Record<string,string>>({}),error=ref('');
async function load(){messages.value=await request('communications/unassigned')}
onMounted(()=>{void load().catch(e=>error.value=String(e))});
async function assign(id:string){try{await request('communications/'+id+'/assign',{inquiry_id:Number(selection.value[id])});await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}}
</script>
<template><section class="inbox"><header><span>{{tx('邮件关联','EMAIL ASSOCIATION')}}</span><h2>{{tx('待关联的客户来信','Messages awaiting a project')}}</h2><p>{{tx('回复会按邮件线程自动关联。只有无法唯一识别项目的来信需要在这里选择一次。','Replies are linked by their mail thread. Only ambiguous messages need a project selection.')}}</p></header><p v-if="error" role="alert">{{error}}</p><article v-for="message in messages" :key="message.id"><small>{{message.sender}}</small><h3>{{message.subject}}</h3><pre>{{message.body}}</pre><div><select v-model="selection[message.id]"><option value="">{{tx('选择关联询价','Select a project')}}</option><option v-for="i in inquiries" :key="i.id" :value="i.id">{{i.company}} / #{{i.id}}</option></select><button type="button" :disabled="!selection[message.id]" @click="assign(message.id)">{{tx('关联并自动整理','Link and process')}}</button></div></article><p v-if="!messages.length" class="empty">{{tx('没有待关联邮件。已匹配的邮件会自动进入对应项目。','No messages awaiting association. Matched emails are archived to their projects automatically.')}}</p></section></template>
<style scoped>
.inbox{color:#1c2922;padding:20px 0}.inbox header>span{font-size:10px;letter-spacing:.12em;color:#82927a}.inbox h2{font-size:28px;font-weight:500;margin:16px 0}.inbox header p,.empty{font-size:13px;line-height:1.8;color:#84917d;max-width:640px}.inbox article{margin-top:24px;padding:24px;background:white;border:1px solid #e0e7dc;border-radius:6px}.inbox small{font-size:11px;color:#809175}.inbox h3{font-size:16px;font-weight:600;margin:12px 0}.inbox pre{font:13px/1.8 var(--font-body);white-space:pre-wrap;max-height:260px;overflow:auto;color:#5e7351}.inbox article>div{display:flex;gap:12px;margin-top:20px}.inbox select{flex:1;padding:11px 12px;border:1px solid #d3decb;border-radius:4px;background:#fff;font:12px var(--font-body);min-width:0}.inbox button{padding:11px 16px;border:1px solid #0f6e5c;background:#0f6e5c;color:#fff;border-radius:4px;font:12px var(--font-body);cursor:pointer}.inbox button:disabled{opacity:.5;cursor:default}@media(max-width:600px){.inbox article{padding:16px}.inbox article>div{flex-direction:column}.inbox h2{font-size:23px}}
</style>
